INSERT INTO public.chef_events (owner_id, slug, title, chef_name, description, event_date, pickup_address, cover_url, menu, status) VALUES ('6bce31f8-b243-40cb-965e-67bad281b9e8', 'moshe-sunday-supper', 'Sunday Supper at Moshe''s', 'Chef Moshe Fhima', 'An intimate Neapolitan pizza night with house-fermented dough and seasonal toppings. BYOB. Limited seats.', '2025-06-15 19:00:00+00', '1037 S Sherbourne Dr, Los Angeles, CA 90035', 'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?auto=format&fit=crop&w=1200&q=80', '[{"name":"Margherita","price":22,"description":"San Marzano tomatoes, fior di latte, basil"},{"name":"La Bianca","price":24,"description":"Ricotta, mozzarella, garlic, rosemary"},{"name":"Nutella Calzone","price":14,"description":"Wood-fired folded pizza with Nutella & powdered sugar"}]', 'published') ON CONFLICT (slug) DO UPDATE SET status = 'published', title = 'Sunday Supper at Moshe''s' RETURNING id, slug;